/// <summary>
/// Worker sign-in history: one row per session on a handheld - who, on which device and in which
/// warehouse, when they signed in, when the session ended and how long it lasted.
///
/// Written by the app (HSMobileOpsSignInLogSvc), not by sign-in itself, so a session signed in
/// offline is recorded too - the app keeps it and sends it once D365FO can be reached. A session
/// is sent twice: when it starts and again when it ends; SessionId (made on the handheld) ties
/// the two together, so a resend changes nothing.
///
/// One history for the whole environment, like HSMobileOpsDevice.
/// </summary>
public class HSMobileOpsSignInLog extends common
{
}

Method.Source:
public static HSMobileOpsSignInLog findBySessionId(str _sessionId, boolean _forUpdate = false)
{
    HSMobileOpsSignInLog log;

    if (_sessionId)
    {
        log.selectForUpdate(_forUpdate);
        select firstonly log
            where log.SessionId == _sessionId;
    }
    return log;
}

/// <summary>
/// Duration from the sign-in and sign-out times, in minutes and as hours:minutes ("7:42").
/// Stored, not a display method - those show blank on this environment's forms.
/// </summary>
public void setDuration()
{
    int64 seconds;
    int   minutes;

    if (!this.SignInUtc || !this.SignOutUtc || this.SignOutUtc < this.SignInUtc)
    {
        this.DurationMinutes = 0;
        this.DurationText    = '';
        return;
    }
    seconds = DateTimeUtil::getDifference(this.SignOutUtc, this.SignInUtc);
    this.DurationMinutes = round(seconds / 60.0, 0.01);
    minutes = real2int(roundDown(seconds / 60.0, 1));
    this.DurationText = strFmt('%1:%2', minutes div 60, strRFix(int2Str(minutes mod 60), 2, '0'));
}
